  const MH_STORYLETS = MH_OPTIONS.map(function (e) { return e.storylet; })
    .concat(MH_SHOW_STORYLETS, ['Off to Mahogany Hall'])
    .filter(function (s, i, all) { return all.indexOf(s) === i; });
